static class DSP {
 public const int Rate=48000;
 public static float[] Trim(float[] input,double start,double length){int frames=input.Length/2;if(frames==0)return new float[0];int first=Math.Max(0,Math.Min(frames-1,(int)Math.Round(start*frames)));int count=Math.Max(1,Math.Min(frames-first,(int)Math.Round(length*frames)));if(first==0&&count==frames)return input;var result=new float[count*2];Array.Copy(input,first*2,result,0,result.Length);return result;}
 public static float[] Region(float[] input,double start,double length){var cropped=Trim(input,start,length);int wanted=Math.Max(1,(int)Math.Round(input.Length/2*length))*2;if(wanted<=cropped.Length)return cropped;var padded=new float[wanted];Array.Copy(cropped,padded,cropped.Length);int frames=cropped.Length/2,fade=Math.Min(240,frames);for(int i=0;i<fade;i++){double gain=.5-.5*Math.Cos(Math.PI*i/fade);int p=(frames-1-i)*2;padded[p]*=(float)gain;padded[p+1]*=(float)gain;}return padded;}
 public static float Sample(float[] a,double p,int ch) { int n=a.Length/2; if(n==0)return 0; p=(p%n+n)%n; int i=(int)p,j=(i+1)%n; return (float)(a[i*2+ch]*(1-(p-i))+a[j*2+ch]*(p-i)); }
 public static float[] Render(float[] input,double stretch,double semitones,bool reverse,CancellationToken cancel=default(CancellationToken),bool formants=false){return QualityRender.Render(input,stretch,semitones,reverse,cancel,formants);}
 public static void Wav(string path,float[] samples,int repeats=1,CancellationToken cancel=default(CancellationToken)){using(var b=new BinaryWriter(File.Create(path))){b.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));b.Write(48+samples.Length*4*repeats);b.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));b.Write(16);b.Write((short)3);b.Write((short)2);b.Write(Rate);b.Write(Rate*8);b.Write((short)8);b.Write((short)32);b.Write(System.Text.Encoding.ASCII.GetBytes("fact"));b.Write(4);b.Write(samples.Length/2*repeats);b.Write(System.Text.Encoding.ASCII.GetBytes("data"));b.Write(samples.Length*4*repeats);byte[] bytes=new byte[65536];for(int repeat=0;repeat<repeats;repeat++)for(int offset=0;offset<samples.Length;){cancel.ThrowIfCancellationRequested();int count=Math.Min(bytes.Length/4,samples.Length-offset);System.Buffer.BlockCopy(samples,offset*4,bytes,0,count*4);b.Write(bytes,0,count*4);offset+=count;}}}
}
