 void AddRegion(Panel panel,Layer t,Color color){
  bool updating=false;double duration=Math.Max(.001,t.Original.Length/(2.0*DSP.Rate));
  var row=new FlowLayoutPanel{Location=new Point(8,268),Size=new Size(440,32),WrapContents=false};panel.Controls.Add(row);
  var start=new StudioNumber{DecimalPlaces=3,Increment=.010m,Minimum=0,Maximum=(decimal)Math.Max(0,duration-.001),Width=76,BackColor=Skin.Ink,ForeColor=color,BorderStyle=BorderStyle.FixedSingle,Font=new Font("Consolas",11),AccessibleName="Loop start in source seconds"};
