  Action sync=()=>{updating=true;try{start.Value=Math.Max(start.Minimum,Math.Min(start.Maximum,(decimal)(t.TrimStart*duration)));length.Maximum=(decimal)Math.Max(300,duration*t.Stretch);length.Value=Math.Max(length.Minimum,Math.Min(length.Maximum,(decimal)(t.TrimLength*duration*t.Stretch)));}finally{updating=false;}};
