  foreach(var action in new[]{"½","×2","FULL"}){string label=action;var b=Btn(label,()=>{if(label=="FULL"){t.TrimStart=0;t.TrimLength=1;Process(t);}else length.Value=Math.Max(length.Minimum,Math.Min(length.Maximum,label=="½"?length.Value/2:length.Value*2));});b.Size=new Size(48,27);b.Margin=new Padding(3,0,0,0);row.Controls.Add(b);}
